import React, { useState } from "react";
import ProductForm from "./components/ProductForm";
import ProductList from "./components/ProductList";
import api from "./api";

function App() {
  // Estado para forçar a atualização da lista
  const [refreshKey, setRefreshKey] = useState(0);

  const handleProductSaved = () => {
    // Incrementa a key, o que faz o ProductList recarregar
    setRefreshKey((prevKey) => prevKey + 1);
  };

  return (
    <div className="App">
      <h1>Gerenciador de Compra e Venda de Acessórios Musicais</h1>

      {/* Passa a função de callback para o formulário */}
      <ProductForm api={api} onProductSaved={handleProductSaved} />

      {/* Passa a 'key' para a lista. Quando a key mudar, o componente recarrega */}
      <ProductList api={api} key={refreshKey} />

      {/* Você pode remover o Simulation.js se não for mais usá-lo */}
      {/* <Simulation /> */}
    </div>
  );
}

export default App;
